const stages=['Discovered','Qualified','Outreach','Meeting booked','Mandate'];
const links=[['overview','◫','Mission Control'],['opportunities','⌕','Opportunity intelligence'],['pipeline','▥','Capital pipeline'],['gtm','↗','GTM playbooks'],['appointments','▦','Appointments'],['metrics','◴','Success metrics'],['wireframe','◇','SaaS blueprint'],['brain','◇','Client Brain'],['settings','⚙','Team settings']];
const seed=[
{id:1,name:'Willow Creek Residences',company:'Cedarline Development',city:'Surrey',type:'Multifamily',phase:'Rezoning approved',budget:24,amount:15.6,score:92,signal:'Rezoning milestone',fit:'Construction financing',stage:'Qualified',need:'Unknown — sponsor confirmation required',contact:'Morgan Lee · Development principal',verified:false,source:'Synthetic planning milestone · not a real public record',action:'Verify sponsor and discuss financing timeline',note:'Proposed 62-unit rental development. Planning milestone is a reason to research, not evidence that the sponsor needs a lender.'},
{id:2,name:'Harbour Exchange',company:'Westhaven Properties',city:'Vancouver',type:'Office / retail',phase:'Acquisition',budget:18,amount:11.7,score:88,signal:'Acquisition signal',fit:'Acquisition & bridge',stage:'Outreach',need:'Confirmed in sample discovery notes',contact:'Taylor Chen · Managing partner',verified:true,source:'Synthetic acquisition notice · demonstration only',action:'Follow up on a 15-minute capital planning call',note:'Sample sponsor seeking to evaluate acquisition and repositioning capital. Borrower authority, timing and capital stack still require verification.'},
{id:3,name:'Fraser Logistics Centre',company:'Northcrest Industrial',city:'Langley',type:'Industrial',phase:'Development permit',budget:32,amount:20.8,score:85,signal:'Permit milestone',fit:'Development financing',stage:'Discovered',need:'Unknown — sponsor confirmation required',contact:'Jordan Patel · Director, development',verified:false,source:'Synthetic permit event · demonstration only',action:'Resolve project entity and verify decision-maker',note:'Proposed light industrial space. Check sponsor identity, appointment authority, existing lender and financing stage before outreach.'},
{id:4,name:'Parkside Rental Collection',company:'Evergreen Living',city:'Burnaby',type:'Multifamily',phase:'Stabilization',budget:16,amount:10.4,score:82,signal:'Lease-up milestone',fit:'Term refinance',stage:'Meeting booked',need:'Confirmed in sample discovery notes',contact:'Alex Wong · Finance director',verified:true,source:'Synthetic occupancy event · demonstration only',action:'Prepare refinance discovery brief',note:'Sample operating rental property approaching stabilized occupancy. Verify current debt, payout restrictions, NOI and financing date.'},
{id:5,name:'Pacific Trade Campus',company:'Summit Commercial',city:'Abbotsford',type:'Industrial',phase:'Preconstruction',budget:12,amount:7.8,score:78,signal:'Sponsor expansion',fit:'Owner-occupied purchase',stage:'Qualified',need:'Unknown — sponsor confirmation required',contact:'Jamie Ross · Business owner',verified:false,source:'Synthetic expansion event · demonstration only',action:'Confirm ownership, intended use and purchase timing',note:'Sample business growth signal may justify an owner-occupied property discussion. Growth alone does not establish borrowing intent.'},
{id:6,name:'Oak & Alder Medical',company:'Alder Healthcare Properties',city:'Richmond',type:'Office / retail',phase:'Operating',budget:9,amount:5.8,score:75,signal:'Referral introduction',fit:'Commercial refinance',stage:'Mandate',need:'Confirmed in sample discovery notes',contact:'Casey Park · Asset manager',verified:true,source:'Synthetic referral · demonstration only',action:'Collect property and borrower documents',note:'Sample mandate with underwriting outstanding. A mandate is not loan approval or committed financing.'}];
const base={opps:seed,meetings:[{id:1,opp:4,name:'Parkside Rental Collection',contact:'Alex Wong',date:'2026-10-20',time:'10:00',status:'Booked',qualified:true,channel:'Refinance readiness',outcome:''},{id:2,opp:6,name:'Oak & Alder Medical',contact:'Casey Park',date:'2026-10-21',time:'14:00',status:'Held',qualified:true,channel:'Referral partners',outcome:'Mandate discussion; document collection next.'}],tasks:[false,false,false],logs:[],goal:8,profile:{name:'Dennis Eng & Associates',territory:'Metro Vancouver & Fraser Valley',min:'2',max:'50',focus:'Commercial mortgages & development finance',strength:'Sponsor relationships, construction and commercial lending',gap:'Verify decision-maker access and current lender status'},planner:{contacts:100,reply:20,qual:50,book:80,held:75},campaigns:{}};
let state;try{state=JSON.parse(localStorage.getItem('kommercial-v1'))||structuredClone(base)}catch{state=structuredClone(base)}let page='overview';let dragged=null;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'$'+Number(n).toFixed(1)+'M';
function save(){localStorage.setItem('kommercial-v1',JSON.stringify(state))}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}function log(t){state.logs.unshift({text:t,date:new Date().toLocaleString('en-CA',{timeZone:'America/Vancouver'})});save()}function nav(p){page=p;location.hash=p;render()}window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'overview';render()});
function head(title,sub,actions=''){return `<div class="pagehead"><div><div class="eyebrow" style="margin-bottom:8px">CAPITAL ORIGINATION / BC FIRST</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`}
function stats(){let booked=state.meetings.filter(m=>m.status==='Booked').length,held=state.meetings.filter(m=>m.status==='Held'&&m.qualified).length,q=state.opps.filter(o=>o.verified).length;return `<div class="stats"><div class="stat"><div class="label">Qualified meetings held <span>↗</span></div><div class="value">${held} <em>/ ${state.goal} target</em></div><small><span class="green">North-star outcome</span> · sample records</small></div><div class="stat"><div class="label">Upcoming appointments <span>▦</span></div><div class="value">${booked.toString().padStart(2,'0')}</div><small>Booked · awaiting meeting outcome</small></div><div class="stat"><div class="label">Sponsor-confirmed needs <span>◎</span></div><div class="value">${q.toString().padStart(2,'0')} <em>/ ${state.opps.length} opportunities</em></div><small>Sample confirmation · verify before use</small></div><div class="stat"><div class="label">Potential financing volume <span>▥</span></div><div class="value">${money(state.opps.reduce((a,o)=>a+o.amount,0))}</div><small>Illustrative estimates · no commitments</small></div></div>`}
function row(o){return `<article class="opprow" tabindex="0" role="button" aria-label="Open ${esc(o.name)}" onclick="detail(${o.id})" onkeydown="if(event.key==='Enter')detail(${o.id})"><div class="building">▥</div><div class="opptext"><h3>${esc(o.name)}</h3><div class="oppmeta">${esc(o.company)} &nbsp;·&nbsp; ${esc(o.city)}, ${esc(o.province||'BC')} &nbsp;·&nbsp; ${esc(o.type)}</div><span class="tag teal">${esc(o.signal)}</span>${state.brain?`<span class="tag ${matchBrain(o).eligible&&!matchBrain(o).unknown?'blue':'amber'}">${matchBrain(o).unknown?'Review required':matchBrain(o).eligible?'Mandate match':'Outside mandate'}</span>`:''}<span class="tag ${o.verified?'blue':'amber'}">${o.verified?'Sample need confirmed':'Need unconfirmed'}</span></div><div class="oppvalue"><strong>${money(o.amount)}</strong><small>Est. financing</small><div class="score">${state.brain?matchBrain(o).score:o.score} ${state.brain?'specialization fit':'sample fit'} ↗</div></div><span class="chevron">›</span></article>`}
function list(limit){return `<div class="panel"><div class="panelhead"><div><h2>${limit?'Your next best conversations':'Opportunity intelligence'}</h2><p>${state.brain?'Ranked by Client Brain. Outside-mandate records remain visible in the full list.':'Activate Client Brain to rank by specialization.'} All records are illustrative.</p></div><button class="textbutton" onclick="nav('opportunities')">${limit?'View all ↗':'All opportunities'}</button></div>${limit?`<div class="prioritybanner"><span class="symbol">✧</span><span><b>Start with the sponsor, not the loan.</b><br>Confirm financing need before adding an opportunity to outreach.</span><button class="textbutton" onclick="nav('gtm')">View strategy →</button></div>`:`<div class="filters"><input id="search" aria-label="Search opportunities" placeholder="Search project, sponsor or city…" oninput="filterList()"><select id="type" aria-label="Property type" onchange="filterList()"><option>All property types</option>${propertyOptions.map(p=>`<option>${esc(p)}</option>`).join('')}</select><select id="need" aria-label="Need status" onchange="filterList()"><option>Any need status</option><option>Confirmed</option><option>Unconfirmed</option></select></div>`}<div id="oppList">${rankedOpps(!!limit).slice(0,limit||99).map(row).join('')||(state.brain&&limit?'<div class="empty">No sample opportunities match your active Client Brain. Review your mandate or add relevant opportunities.</div>':'')}</div><div class="panelbottom"><span>${state.opps.length} sample opportunities · BC launch region</span><span>Evidence before outreach</span></div></div>`}
function overview(){let held=state.meetings.filter(m=>m.status==='Held'&&m.qualified).length;return head('Make your next conversation count.',state.brain?'Your specialization drives the shortlist. Workspace totals include all records.':'Your commercial financing opportunities, relationships and next steps — in one place.',`<button onclick="nav('metrics')">◴ &nbsp; View outcomes</button><button class="primary" onclick="addOpp()">＋ Add opportunity</button>`)+brainBanner()+stats()+`<div class="layout"><section>${list(4)}<div class="panel"><div class="panelhead"><div><h2>Capital origination pipeline</h2><p>Relationship stages, separate from the construction lifecycle.</p></div><button class="textbutton" onclick="nav('pipeline')">Open board ↗</button></div><div class="pipeline">${stages.map(s=>`<div class="pipe"><div class="bar"></div><b>${state.opps.filter(o=>o.stage===s).length}</b><small>${s}</small></div>`).join('')}</div></div><div class="panel"><div class="panelhead"><div><h2>A reason to reach out.</h2><p>Use a relevant project trigger to earn a financing conversation.</p></div><button class="textbutton" onclick="nav('gtm')">All playbooks ↗</button></div>${recommendedPlays().slice(0,2).map(i=>{let p=plays[i];return `<div class="strategyrow"><span class="strategyicon">${p.icon}</span><div><h3>${p.name}</h3><p>${p.short}</p></div><button class="textbutton" onclick="play(${i})">Open playbook →</button></div>`}).join('')}</div></section><section class="rightcol"><div class="goalcard"><div class="eyebrow">THE OUTCOME THAT MATTERS</div><h2>Qualified conversations.<br>Stronger financing pipeline.</h2><div class="goalnumber">${held.toString().padStart(2,'0')} <span>/ ${state.goal} held this month</span></div><div class="progress"><div style="width:${Math.min(100,held/state.goal*100)}%"></div></div><p>Target is a planning assumption.<br>Booked appointments count after they’re held and qualified.</p></div><div class="panel"><div class="panelhead"><h2>Today’s focus</h2><span class="subtle">${brainFocus().length} actions</span></div>${brainFocus().map((a,i)=>`<label class="task"><input type="checkbox" ${state.tasks[i]?'checked':''} onchange="state.tasks[${i}]=this.checked;save()"><span>${a[0]}<small>${a[1]}</small></span><span class="time">${a[2]}</span></label>`).join('')}</div><div class="panel"><div class="panelhead"><h2>On the calendar</h2><button class="textbutton" onclick="nav('appointments')">View all ↗</button></div>${state.meetings.filter(m=>m.status==='Booked').slice(0,3).map(m=>`<div class="meeting"><div class="date">${esc(m.date.slice(5,7))}<strong>${esc(m.date.slice(8))}</strong></div><div><b>${esc(m.name)}</b><small>${esc(m.time)} · Vancouver time · 15 min</small><small>${esc(m.channel)}</small></div></div>`).join('')||'<div class="empty">No upcoming appointments.</div>'}</div><div class="notice">Demo workspace: sample prospects, scores and financing estimates. No live data sources or calendars are connected.</div></section></div>`}
function filterList(){let q=$('#search').value.toLowerCase(),t=$('#type').value,n=$('#need').value;$('#oppList').innerHTML=rankedOpps().filter(o=>(o.name+' '+o.company+' '+o.city).toLowerCase().includes(q)&&(t==='All property types'||o.type===t)&&(n==='Any need status'||o.verified===(n==='Confirmed'))).map(row).join('')||'<div class="empty">No matching opportunities. Try another filter.</div>'}
function pipeline(){return head('Every opportunity has a next step.','Drag cards between stages, or open a card to qualify and advance the relationship.',`<button onclick="exportData()">↓ Export data</button><button class="primary" onclick="addOpp()">＋ Add opportunity</button>`)+`<div class="board">${stages.map((s,i)=>`<section class="column" ondragover="event.preventDefault()" ondrop="drop(event,${i})"><div class="colhead"><span>${s}</span><span>${state.opps.filter(o=>o.stage===s).length}</span></div>${state.opps.filter(o=>o.stage===s).map(o=>`<article class="kanbancard" draggable="true" ondragstart="dragged=${o.id}"><span class="tag ${o.verified?'teal':'amber'}">${o.verified?'Need confirmed':'Need unconfirmed'}</span><h3 style="margin-top:10px">${esc(o.name)}</h3><p>${esc(o.city)} · ${esc(o.fit)}</p><b>${money(o.amount)}</b><small>Estimated financing · sample</small><p>Next: ${esc(o.action)}</p><button class="textbutton" onclick="detail(${o.id})">Expand opportunity ↗</button></article>`).join('')}</section>`).join('')}</div><div class="notice">Qualified = sponsor, fit and timing reviewed. Meeting booked requires a booking record. Mandate = engagement recorded; financing remains subject to underwriting. Construction stage is stored independently.</div>`}
function drop(e,i){e.preventDefault();if(dragged)advance(dragged,i);dragged=null}function advance(id,i){let o=state.opps.find(x=>x.id===id);if(i===3){booking(id);return}if(i===2&&!o.verified){toast('Confirm financing need in the opportunity before moving to outreach.');return}o.stage=stages[i];log(`${o.name} moved to ${stages[i]}`);render()}
const plays=[{name:'Project milestone outreach',icon:'◇',short:'Planning change → sponsor introduction',audience:'Developers with verified rezoning, acquisition or permit changes',trigger:'A dated source shows a relevant project milestone. Verify entity, decision-maker and current financing position.',offer:'15-minute construction capital readiness conversation',steps:['Research the dated project event and establish sponsor identity.','Verify financing timing, existing lender and authority.','Review contact permission, personalize the draft, and approve it manually.','If there is no response, plan two respectful follow-ups over 14 days; then pause.','Offer a 15-minute discovery slot after a positive reply.'],draft:'Hi [First name], I noticed [verified project milestone] for [Project]. Are you already covered for the next financing stage? If it would help, I can walk through the construction capital requirements with you in a 15-minute call. Would [option A] or [option B] work?'},
{name:'Refinance readiness',icon:'↻',short:'Verified maturity or lease-up → refinance review',audience:'Commercial owners with verified refinance or stabilization timing',trigger:'Owner-confirmed maturity, lease-up or portfolio review. Never infer mortgage terms from a public permit.',offer:'Current debt and refinance readiness review',steps:['Confirm the owner and obtain reliable debt or lease-up timing.','Check consent, existing broker relationships and contact suitability.','Prepare questions on balance, maturity, NOI and intended hold.','Offer a brief review and follow up on the agreed date.','Record the meeting outcome and a specific next action.'],draft:'Hi [First name], you mentioned [confirmed timing] for [Property]. A short review of the current debt and refinance requirements may help you plan the next step. Would a 15-minute call on [option A] or [option B] be useful?'},
{name:'Referral partner introductions',icon:'⇄',short:'Accountants, CRE advisors & lawyers → warm introduction',audience:'Trusted referral partners supporting commercial property owners',trigger:'A partner identifies a client situation and has permission to introduce the parties.',offer:'Joint financing discovery with a concise referral brief',steps:['Identify partners whose clients match your financing mandate.','Agree on the ideal referral and permitted information sharing.','Ask for a permissioned introduction with context.','Book a short joint call and confirm the agenda.','Close the loop with the partner where the client permits it.'],draft:'Hi [Partner], I help with [specific financing mandate]. If a client is planning a commercial purchase, construction project or refinance, I can offer a short initial review. Would it be useful to compare the situations where an introduction would make sense?'},
{name:'Business growth → property conversation',icon:'↗',short:'Expansion signal → owner-occupied financing discovery',audience:'Established businesses considering space or property expansion',trigger:'Verified expansion or relocation signal. Growth does not establish borrowing intent.',offer:'Own versus lease and financing discovery',steps:['Validate the business identity and expansion signal.','Ask whether new space is being leased or purchased.','Qualify ownership, use, timing and business cash-flow context.','Offer a discovery call relevant to the stated plans.','Route to the appropriate licensed broker for the financing scope.'],draft:'Hi [First name], I saw [verified expansion announcement]. Are you considering a property purchase as part of the move, or planning to lease? If a purchase is on the table, I can offer a short discussion about the financing information you would need.'},
{name:'Evidence-led inbound',icon:'⌕',short:'Local commercial finance content → booked consultation',audience:'BC owners actively researching commercial finance',trigger:'A prospect requests a consultation through a focused landing page.',offer:'Property-specific financing discovery',steps:['Build one useful page for a property type and local financing question.','Use dated sources; label examples and avoid unsupported rate promises.','Collect purpose, property, amount, timing and contact permission.','Review fit and send the prospect available booking options.','Track page → request → booked → held qualified meeting.'],draft:'Thanks for your enquiry about [financing purpose]. Before our call, could you confirm [property type], [amount] and [timing]? Here are two available 15-minute slots: [option A] or [option B].'},
{name:'Permissioned database reactivation',icon:'◎',short:'Existing relationships → updated financing plans',audience:'Existing contacts with a reviewed basis for recontact',trigger:'An agreed follow-up date or permissioned relationship review.',offer:'A short financing plans update',steps:['Review contact history and permitted communication basis.','Remove opt-outs, duplicates and contacts with no appropriate basis.','Segment by last discussion and relevant property needs.','Ask one specific question and offer a short conversation.','Record the response, next date or suppression immediately.'],draft:'Hi [First name], when we last spoke you were considering [previously discussed plan]. Has the timing changed? If it is still relevant, I would be happy to set up a short call to review the next steps.'}];
function gtm(){return head('A relevant reason. A real conversation.','Six appointment-focused plays for commercial mortgage and finance brokers.',`<button onclick="nav('metrics')">Open funnel planner ↗</button>`)+`<div class="steps"><span>01 · Verify signal</span><span>02 · Qualify fit</span><span>03 · Review contact basis</span><span>04 · Approve outreach</span><span>05 · Book discovery</span><span>06 · Record outcome</span></div><div class="cards">${recommendedPlays().concat(plays.map((p,i)=>i)).filter((v,i,a)=>a.indexOf(v)===i).map(i=>{let p=plays[i];return `<article class="panel playcard"><span class="eyebrow">PLAYBOOK 0${i+1} ${state.brain?.answers.channels.includes(p.name)?'· PREFERRED':''} &nbsp; ${state.campaigns[i]?'· IN PLAN':''}</span><h2>${p.name}</h2><p>${p.short}</p><p><b>Offer:</b> ${p.offer}</p><ol><li>Validate trigger and mandate fit</li><li>Personalize a human-reviewed approach</li><li>Book and qualify a discovery meeting</li></ol><button onclick="play(${i})">View strategy & outreach draft →</button></article>`}).join('')}</div>`}
function play(i){let p=plays[i];modal(p.name,'APPOINTMENT PLAYBOOK',`<p><b>Audience:</b> ${p.audience}</p>${state.brain?`<div class="wirebox"><b>Client Brain briefing</b><p>Ideal client: ${esc(state.brain.answers.ideal)}</p><p>Call offer: ${esc(state.brain.answers.offer)}</p><p>Strengths: ${esc(state.brain.answers.strength)}</p><p>Contact instructions: ${esc(state.brain.answers.restrictions||'None stated; review contact basis before use.')}</p></div>`:''}<p><b>Trigger:</b> ${p.trigger}</p><p><b>Offer:</b> ${p.offer}</p><h3>Execution sequence</h3><ol>${p.steps.map(s=>`<li>${s}</li>`).join('')}</ol><h3>Editable outreach draft</h3><textarea id="draft" style="width:100%;height:150px">${esc(state.campaigns[i]?.draft||p.draft)}</textarea><p>Personalize the bracketed fields. Review contact permission and any applicable requirements before use. This prototype does not send messages.</p><h3>Measure the result</h3><p>Eligible prospects → replies → qualified conversations → bookings → held qualified meetings → mandates. Attribute every appointment to its source playbook.</p>`,`<button onclick="savePlay(${i})">Save to GTM plan</button><button class="primary" onclick="copyDraft()">Copy draft</button>`)}function savePlay(i){state.campaigns[i]={draft:$('#draft').value};log(`Saved ${plays[i].name} to GTM plan`);$('#dialog').close();render();toast('Playbook and draft saved.')}async function copyDraft(){try{await navigator.clipboard.writeText($('#draft').value);toast('Draft copied.')}catch{toast('Select the draft text to copy it.')}}
function appointments(){return head('From booked to held to qualified.','Track the appointment outcome, source playbook and next financing action.',`<button class="primary" onclick="booking()">＋ Book discovery</button>`)+`<div class="panel tablewrap"><table><thead><tr><th>PROJECT / CONTACT</th><th>DATE · VANCOUVER TIME</th><th>PLAYBOOK</th><th>STATUS</th><th>OUTCOME</th></tr></thead><tbody>${state.meetings.map(m=>`<tr><td><b>${esc(m.name)}</b><small>${esc(m.contact)}</small></td><td>${esc(m.date)}<small>${esc(m.time)} · 15 min</small></td><td>${esc(m.channel)}</td><td><span class="tag ${m.status==='Held'?'teal':'blue'}">${esc(m.status)}</span></td><td><button class="textbutton" onclick="meetingOutcome(${m.id})">${m.outcome?'Review outcome ↗':'Record outcome →'}</button></td></tr>`).join('')}</tbody></table></div><div class="notice">Bookings are internal planning records. No attendee invitation, availability check, reminder or calendar sync is performed. Held qualified meeting = authorized participant confirms a credible project and discusses financing timing or need.</div>`}
function metrics(){return head('Manage the funnel. Measure the conversations.','Separate activity from outcomes, and test the assumptions behind your appointment target.')+stats()+`<div class="plan"><section class="panel"><div class="eyebrow">GTM SCENARIO PLANNER</div><h2 style="margin-top:10px">What could it take to book meetings?</h2><p class="subtitle">Planning assumptions, not forecasts or historical conversion rates.</p>${[['contacts','Eligible contacts per month',10,500,10],['reply','Reply rate %',0,100,1],['qual','Qualified share of replies %',0,100,1],['book','Booking rate of qualified replies %',0,100,1],['held','Show rate %',0,100,1]].map(([k,l,min,max,step])=>`<label for="${k}">${l}<b id="val-${k}">${state.planner[k]}</b></label><input type="range" id="${k}" min="${min}" max="${max}" step="${step}" value="${state.planner[k]}" oninput="planChange('${k}',this.value)">`).join('')}<div id="scenario"></div></section><section class="panel"><div class="eyebrow">PILOT SUCCESS SCORECARD</div><h2 style="margin-top:10px">Prove value before scaling.</h2><div class="metricline"><span>Qualified meetings held / month</span><b><input aria-label="Monthly qualified meeting goal" type="number" min="1" max="100" value="${state.goal}" style="width:70px" onchange="state.goal=Math.max(1,Number(this.value)||8);save();render()"> target</b></div><div class="metricline"><span>Activation: save 5 projects + create 1 opportunity</span><b>7 days</b></div><div class="metricline"><span>Pilot-used records within verification SLA</span><b>≥80% / 7 days</b></div><div class="metricline"><span>Sampled critical assertion accuracy</span><b>≥90%</b></div><div class="metricline"><span>Preparation-time reduction vs baseline</span><b>30% target</b></div><div class="metricline"><span>Paid renewal gate, all pilot cohorts</span><b>5 of 8 teams</b></div><p class="subtitle">Pilot gates come from the supplied PMF document; these are proposed targets, not achieved results. Monthly meeting goal is an editable product assumption.</p><h3 style="margin-top:24px">Attribution rule</h3><p class="subtitle">Link each meeting to one opportunity, origin and primary playbook. Report net-new and assisted discoveries separately. Count held qualified outcomes once; track cancellations and no-shows separately.</p></section></div>`}
function planChange(k,v){state.planner[k]=Number(v);save();$('#val-'+k).textContent=v;scenario()}function scenario(){if(!$('#scenario'))return;let p=state.planner,replies=p.contacts*p.reply/100,q=replies*p.qual/100,b=q*p.book/100,h=b*p.held/100;$('#scenario').innerHTML=`<div class="result">${b.toFixed(1)} <span style="font-size:14px;color:#86968f;font-weight:400">estimated bookings / month</span></div><p class="subtitle">${replies.toFixed(1)} replies → ${q.toFixed(1)} qualified replies → ${b.toFixed(1)} booked → ${h.toFixed(1)} held</p><p class="subtle">Held meetings still need outcome qualification before counting toward the north-star metric.</p>`}
function blueprint(){return head('Designed for brokers. Built to become SaaS.','An interactive wireframe and implementation blueprint for Claude Code or your product team.',`<button onclick="window.print()">Print blueprint</button>`)+`<div class="plan"><section class="panel"><div class="eyebrow">01 / INFORMATION ARCHITECTURE</div><h2 style="margin-top:10px">The broker operating workspace</h2>${[['Mission Control','Outcome cards · prioritized opportunities · tasks · appointments'],['Opportunity intelligence','Search & filters · source provenance · sponsor verification · financing need'],['Capital pipeline','Discovered → Qualified → Outreach → Meeting booked → Mandate'],['GTM playbooks','Audience · trigger · offer · outreach draft · follow-up · attribution'],['Appointments & outcomes','Discovery brief · time · playbook · held / no-show · qualification'],['Client Brain interview','Practice → specialties → capabilities → appointment strategy → reviewed activation']].map(([t,b])=>`<div class="wirebox"><b>${t}</b><p>${b}</p></div>`).join('')}<button class="primary" onclick="nav('overview')">Explore working interface →</button></section><section class="panel"><div class="eyebrow">02 / SAAS DELIVERY PLAN</div><h2 style="margin-top:10px">From prototype to a paid broker pilot</h2><h3 style="margin-top:20px">Phase 1 · Trusted origination core</h3><p class="subtitle">Tenant-scoped organization and membership, broker profile, verified project ingestion, source dates, entity matching, qualification, persistent pipeline and audit trail.</p><h3 style="margin-top:20px">Phase 2 · Appointments & integrations</h3><p class="subtitle">Connect CRM and calendar; check availability before booking; invitation approval; deduplicate contacts and events; suppression checks; outcome attribution and human-approved outreach.</p><h3 style="margin-top:20px">Phase 3 · Commercial pilot</h3><p class="subtitle">Team roles, subscription entitlements, quotas, billing, onboarding and export/deletion workflows. Test CAD $299–$799 per team/month from the PMF document; pricing is unvalidated.</p><h3 style="margin-top:20px">Core records</h3><div class="steps">${['Organization','Membership','BrokerProfile','Project','SourceEvidence','Company','Contact','Opportunity','Playbook','OutreachReview','Appointment','Outcome','AuditEvent'].map(t=>`<span>${t}</span>`).join('')}</div><p class="subtitle">All business records require organization_id. Enforce server-side authorization and tenant isolation on every read/write; test cross-tenant access before pilot onboarding.</p><h3 style="margin-top:20px">Integration contracts</h3><p class="subtitle">LeadSniperAI → discovery. Business-data provider → entity enrichment. Harvey → qualification support and proposed booking. CRM → relationship history. Calendar → confirmed availability and invitations. Each needs authenticated APIs, provenance, review gates, retries and idempotency; none is connected here.</p><h3 style="margin-top:20px">Release acceptance</h3><p class="subtitle">Prove isolated tenants, real dated sources, persistent audit history, valid contact basis, approved outreach, duplicate-safe bookings and end-to-end meeting outcome attribution. Never treat a permit as confirmed funding demand.</p><div class="notice" style="margin-top:20px">Current build: interactive browser-local prototype with sample records. Live ingestion, authentication, multi-tenant storage, subscriptions, email and calendar integrations are production work still to implement.</div></section></div>`}
function settings(){let p=state.profile;return head('Your mandate is the matching engine.','Define the opportunities you want, your strengths and what must be verified.')+`<form class="panel settings" onsubmit="saveProfile(event)"><h2>Team profile</h2><p><button type="button" class="textbutton" onclick="nav('brain')">Customize matching through the Client Brain interview →</button></p><p class="subtitle">Used to shape qualification, opportunity fit and outreach.</p><div class="formgrid">${[['name','Team / brokerage'],['territory','Target territory'],['min','Minimum financing · CAD millions'],['max','Maximum financing · CAD millions'],['focus','Preferred financing opportunities'],['strength','Team strengths'],['gap','Gaps and verification priorities']].map(([k,l])=>`<label class="${['focus','strength','gap'].includes(k)?'wide':''}">${l}<input name="${k}" value="${esc(p[k])}" required ${['min','max'].includes(k)?'type="number" min="0" step="0.1"':''}></label>`).join('')}</div><div class="notice">Client Brain controls opportunity ranking, preferred plays and goals. These legacy team fields are administrative context; edit and activate the Client Brain interview to change matching.</div><div class="actions" style="margin-top:20px"><button class="primary">Save broker profile</button><button type="button" onclick="exportData()">Export workspace JSON</button><button type="button" onclick="resetDemo()">Reset demo</button></div></form>`}function saveProfile(e){e.preventDefault();let p=Object.fromEntries(new FormData(e.target));if(Number(p.min)>Number(p.max)){toast('Minimum financing must be below the maximum.');return}state.profile=p;save();toast('Broker profile saved.')}function resetDemo(){modal('Reset the sample workspace?','DEMO DATA','<p>This replaces changes in this browser with the original sample data. Export your workspace first if you want to keep it.</p>','<button class="primary" onclick="state=structuredClone(base);save();document.querySelector(\'#dialog\').close();render();toast(\'Demo reset.\')">Reset sample data</button>')}
function activity(){return head('Workspace activity','Changes made in this browser are recorded here.')+`<div class="panel">${state.logs.map(l=>`<div class="activityline">${esc(l.text)}<small>${esc(l.date)} · Vancouver time</small></div>`).join('')||'<div class="empty">No changes yet. Qualify an opportunity or save a GTM playbook to get started.</div>'}</div>`}
function render(){document.title='KommercialOS | '+(links.find(x=>x[0]===page)?.[2]||'Mission Control');$('#nav').innerHTML=links.map(([id,ic,l])=>`<button class="${page===id?'active':''}" onclick="nav('${id}')"><span>${ic}</span>${l}${id==='opportunities'?`<span class="count">${state.opps.length}</span>`:''}</button>`).join('');$('#crumb').textContent=links.find(x=>x[0]===page)?.[2]||'Activity';$('#main').innerHTML=({overview,opportunities:()=>head('Find the right opportunity, earlier.','Project intelligence becomes useful when the sponsor, fit and timing are verified.',`<button class="primary" onclick="addOpp()">＋ Add opportunity</button>`)+list(),pipeline,gtm,appointments,metrics,wireframe:blueprint,brain:brainPage,settings,activity}[page]||overview)();scenario();const identity=document.querySelector('.workspace>span:nth-child(2)');if(identity){identity.textContent=state.brain?.answers.name||state.profile.name;const sub=document.createElement('small');sub.textContent=state.brain?'Client Brain active · v'+state.brain.version:'Client Brain not activated';identity.appendChild(sub)}}
function modal(title,kicker,body,foot=''){if($('#dialog').open)$('#dialog').close();$('#modal').innerHTML=`<div class="modalhead"><div><div class="eyebrow" style="margin-bottom:8px">${kicker}</div><h2>${esc(title)}</h2></div><button class="icon" aria-label="Close dialog" onclick="document.querySelector('#dialog').close()">×</button></div><div class="modalbody">${body}</div>${foot?`<div class="modalfoot">${foot}</div>`:''}`;$('#dialog').showModal()}
function detail(id){let o=state.opps.find(x=>x.id===id);modal(o.name,'OPPORTUNITY BRIEF · SAMPLE RECORD',`<span class="tag teal">${esc(o.stage)}</span><span class="tag">${esc(o.city)} · ${esc(o.type)}</span><div class="details"><div><small>Project budget · distinct from debt</small>${money(o.budget)}</div><div><small>Illustrative financing estimate</small>${money(o.amount)} · no commitment</div><div><small>Construction / property stage</small>${esc(o.phase)}</div><div><small>${state.brain?'Specialization fit · rules-based':'Mandate fit score · illustrative'}</small>${state.brain?matchBrain(o).score:o.score}/100 · ${state.brain?'Client Brain rules':'illustrative sample'}</div></div>${brainDetail(o)}<h3>Specialty discovery questions</h3><ul>${discoveryQuestions(o).map(q=>`<li>${esc(q)}</li>`).join('')}</ul><h3>Sponsor & decision-maker</h3><p>${esc(o.company)}<br>${esc(o.contact)}<br>Identity and authority are demonstration fields, not independently verified.</p><h3>Evidence & financing need</h3><p>${esc(o.source)}<br>Verification date: not verified; synthetic sample.</p><p>${esc(o.note)}</p><label class="task" style="border:1px solid var(--line);border-radius:7px"><input type="checkbox" id="confirmed" ${o.verified?'checked':''}><span>Financing need confirmed in sample discovery<small>For the demo only. Production requires source, date, authorized participant and notes.</small></span></label><h3>Next action</h3><input id="nextAction" value="${esc(o.action)}" style="width:100%"><h3>Relationship stage</h3><select id="stageSelect" style="width:100%">${stages.map(s=>`<option ${s===o.stage?'selected':''}>${s}</option>`).join('')}</select>`,`<button onclick="booking(${id})">Book discovery</button><button class="primary" onclick="saveOpp(${id})">Save qualification</button>`)}
function saveOpp(id){let o=state.opps.find(x=>x.id===id),s=$('#stageSelect').value,v=$('#confirmed').checked;if(s==='Outreach'&&!v){toast('Confirm financing need before moving to outreach.');return}if(s==='Meeting booked'&&!state.meetings.some(m=>m.opp===id&&m.status==='Booked')){toast('Use Book discovery to create an appointment record.');return}o.verified=v;o.need=v?'Confirmed in sample discovery notes':'Unknown — sponsor confirmation required';o.stage=s;o.action=$('#nextAction').value;log(`Updated qualification for ${o.name}`);$('#dialog').close();render();toast('Opportunity updated.')}
function addOpp(){modal('Add an opportunity','NEW BROKER OPPORTUNITY',`<form id="oppForm" class="formgrid"><label>Project name<input name="name" required></label><label>Sponsor / company<input name="company" required></label><label>City<input name="city" required></label><label>Province<select name="province"><option>BC</option><option>AB</option><option>ON</option><option>Other Canada</option></select></label><label class="wide">Financing purpose<select name="purpose">${purposeOptions.map(p=>`<option>${esc(p)}</option>`).join('')}</select></label><label>Property type<select name="type"><option>Multifamily</option><option>Industrial</option><option>Office / retail</option><option>Mixed-use</option><option>Land</option><option>Hospitality</option><option>Other commercial</option><option>Business / no property</option></select></label><label>Project budget · CAD millions<input name="budget" type="number" min="0" step="0.1" required></label><label>Financing estimate · CAD millions<input name="amount" type="number" min="0" step="0.1" required></label><label class="wide">Next action<input name="action" required placeholder="Verify sponsor and financing timing"></label></form><p>Added records remain unverified. This prototype is for non-sensitive demonstration data.</p>`,`<button class="primary" onclick="createOpp()">Create opportunity</button>`)}function createOpp(){let f=$('#oppForm');if(!f.reportValidity())return;let p=Object.fromEntries(new FormData(f));state.opps.push({...p,id:Date.now(),budget:Number(p.budget),amount:Number(p.amount),score:0,phase:'Unknown',signal:'Manual research',fit:'Qualification pending',stage:'Discovered',need:'Unknown — sponsor confirmation required',contact:'Not identified',verified:false,source:'Manual entry · evidence not supplied',note:'Verify entity, authority, source date, financing need and timing before outreach.'});log(`Created ${p.name}`);$('#dialog').close();render();toast('Opportunity added for verification.')}
function booking(id){modal('Plan a financing discovery call','INTERNAL APPOINTMENT · NO INVITATION',`<form id="bookForm" class="formgrid"><label class="wide">Opportunity<select name="opp" id="bookOpp">${state.opps.map(o=>`<option value="${o.id}" ${o.id===id?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label><label>Attendee<input name="contact" required placeholder="Authorized sponsor or decision-maker"></label><label>Source playbook<select name="channel">${plays.map(p=>`<option>${p.name}</option>`).join('')}<option>Other / manual</option></select></label><label>Date<input name="date" type="date" required></label><label>Time · America/Vancouver<input name="time" type="time" required value="10:00"></label><label class="wide">Agenda<input name="agenda" required value="15-minute financing need and timing discovery"></label></form><div class="notice" style="margin-top:18px">Confirm the participant’s agreement and availability externally. This saves a local planning record only; no calendar event or attendee message is created.</div>`,`<button class="primary" onclick="createBooking()">Save appointment record</button>`)}function createBooking(){let f=$('#bookForm');if(!f.reportValidity())return;let b=Object.fromEntries(new FormData(f)),o=state.opps.find(x=>x.id===Number(b.opp));if(state.meetings.some(m=>m.date===b.date&&m.time===b.time&&m.status==='Booked')){toast('A booked appointment already occupies that time. Choose another slot.');return}state.meetings.push({...b,id:Date.now(),opp:o.id,name:o.name,status:'Booked',qualified:false,outcome:''});o.stage='Meeting booked';log(`Planned appointment for ${o.name} on ${b.date}`);$('#dialog').close();render();toast('Appointment saved locally. No invitation sent.')}
function meetingOutcome(id){let m=state.meetings.find(x=>x.id===id);modal(m.name,'APPOINTMENT OUTCOME',`<label>Status<select id="meetingStatus" style="display:block;width:100%;margin-top:8px">${['Booked','Held','No-show','Cancelled'].map(s=>`<option ${s===m.status?'selected':''}>${s}</option>`).join('')}</select></label><label class="task" style="margin:16px 0"><input id="meetingQualified" type="checkbox" ${m.qualified?'checked':''}><span>Qualified financing conversation<small>Authorized participant confirms credible project and financing timing or need.</small></span></label><label>Outcome and next step<textarea id="meetingNotes" rows="4" style="display:block;width:100%;margin-top:8px">${esc(m.outcome)}</textarea></label>`,`<button class="primary" onclick="saveOutcome(${id})">Save meeting outcome</button>`)}function saveOutcome(id){let m=state.meetings.find(x=>x.id===id);m.status=$('#meetingStatus').value;m.qualified=m.status==='Held'&&$('#meetingQualified').checked;m.outcome=$('#meetingNotes').value;let o=state.opps.find(x=>x.id===m.opp);if(o&&o.stage==='Meeting booked'&&m.status!=='Booked'&&!state.meetings.some(x=>x.id!==id&&x.opp===m.opp&&x.status==='Booked'))o.stage=m.status==='Held'?'Qualified':'Outreach';log(`Recorded ${m.status.toLowerCase()} outcome for ${m.name}`);$('#dialog').close();render();toast('Meeting outcome saved.')}
function exportData(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='kommercialos-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}const purposeOptions=['Construction / development','Acquisition / bridge','Commercial refinance','Owner-occupied property','Working capital','Equipment financing','Receivables / asset-based lending','Business acquisition'];
const propertyOptions=['Multifamily','Industrial','Office / retail','Mixed-use','Land','Hospitality','Other commercial','Business / no property'];
const brainSections=[
 {title:'Your practice & positioning',intro:'Interview the broker or brokerage owner. This profile describes the client using Mission Control, not an individual borrower application.',fields:[['name','Brokerage / team name','text'],['interviewee','Interview participant and role','text'],['positioning','Who do you help, and what makes your practice a good choice?','textarea'],['ideal','Describe the ideal borrower or sponsor','textarea']]},
 {title:'Your financing specialties',intro:'Select the requests you actively want to originate. Include property and business financing as relevant.',fields:[['purposes','Which financing requests do you specialize in?','checks',purposeOptions],['properties','Which property or asset types do you serve?','checks',propertyOptions],['regions','Which provinces do you actively serve?','checks',['BC','AB','ON','Other Canada']],['cities','Preferred cities, comma-separated · optional','text'],['min','Minimum financing amount · CAD millions','number'],['max','Maximum financing amount · CAD millions','number'],['exclusions','Specific situations you do not handle · manual review','textarea']]},
 {title:'Capability & lender access',intro:'Capture self-reported capabilities and gaps. These answers help prepare research; they do not establish lender eligibility or lending commitments.',fields:[['strength','What are your strongest skills or relationships?','textarea'],['gap','Where do you need research, qualification or partner support?','textarea'],['lenders','Lender categories / relationships you can approach','textarea'],['experience','Describe relevant completed work or experience; identify what needs verification','textarea'],['qualification','What must be known before you accept a financing discovery call?','textarea']]},
 {title:'Appointment strategy & outcomes',intro:'Choose how you want to create conversations, and set a target your team can support.',fields:[['channels','Preferred appointment strategies','checks',['Project milestone outreach','Refinance readiness','Referral partner introductions','Business growth → property conversation','Evidence-led inbound','Permissioned database reactivation']],['offer','Your discovery-call offer','text'],['goal','Target held qualified meetings per month','number'],['capacity','Maximum new discovery appointments per week','number'],['restrictions','Contact restrictions, exclusions or routing instructions · manual review','textarea']]},
 {title:'Review & activate Client Brain',intro:'Review the interview with the client, then activate the profile. Saved drafts do not change dashboard matching.',fields:[]}
];
function blankBrain(){return {name:state.profile.name,interviewee:'',positioning:'',ideal:'',purposes:[],properties:[],regions:[],cities:'',min:state.profile.min,max:state.profile.max,exclusions:'',strength:state.profile.strength,gap:state.profile.gap,lenders:'',experience:'',qualification:'',channels:[],offer:'15-minute financing discovery call',goal:state.goal,capacity:4,restrictions:''}}
let brainStep=0;
function brainDraft(){if(!state.brainDraft)state.brainDraft=structuredClone(state.brain?.answers||blankBrain());return state.brainDraft}
function choices(key,label,opts,b){return `<fieldset class="brainchoices"><legend>${label}</legend>${opts.map(v=>`<label><input type="checkbox" name="${key}" value="${esc(v)}" ${(b[key]||[]).includes(v)?'checked':''}>${esc(v)}</label>`).join('')}</fieldset>`}
function brainField(f,b){const [k,l,t,opts]=f;if(t==='checks')return choices(k,l,opts,b);return `<label class="${t==='textarea'?'wide':''}">${l}${t==='textarea'?`<textarea name="${k}" rows="3">${esc(b[k])}</textarea>`:`<input name="${k}" type="${t}" value="${esc(b[k])}" ${t==='number'?`min="${['min','max'].includes(k)?'0':'1'}" step="${['min','max'].includes(k)?'0.1':'1'}"`:''}>`}</label>`}
function brainPage(){const b=brainDraft(),section=brainSections[brainStep];return head('Client Brain. Your practice, reflected.','A guided client interview that turns broker specialization into dashboard priorities.',`<button onclick="exportBrain()">↓ Export client.brain.md</button>`)+`<div class="brainlayout"><section class="panel braininterview"><div class="eyebrow">BROKER ONBOARDING INTERVIEW · STEP ${brainStep+1} OF 5</div><div class="brainprogress">${brainSections.map((s,i)=>`<button class="${brainStep===i?'selected':''}" onclick="brainJump(${i})"><span>${i+1}</span>${esc(s.title)}</button>`).join('')}</div><h2 style="font-size:21px;margin:24px 0 10px">${section.title}</h2><p class="subtitle">${section.intro}</p>${brainStep<4?`<form id="brainForm" class="formgrid" style="margin-top:24px" onsubmit="event.preventDefault()">${section.fields.map(f=>brainField(f,b)).join('')}</form>`:brainReview(b)}<div class="actions" style="margin-top:25px;flex-wrap:wrap">${brainStep?'<button onclick="brainMove(-1)">← Back</button>':''}<button onclick="saveBrainDraft()">Save interview draft</button>${brainStep<4?'<button class="primary" onclick="brainMove(1)">Continue →</button>':'<button class="primary" onclick="activateBrain()">Activate Client Brain →</button>'}</div><div id="brainError" role="alert" style="color:#a15b42;font-size:12px;margin-top:14px"></div></section><section><div class="goalcard"><div class="eyebrow">${state.brain?'ACTIVE PROFILE':'INTERVIEW NOT ACTIVATED'}</div><h2>${esc(state.brain?.answers.name||'Build your broker profile')}</h2><p>${state.brain?`${esc(state.brain.answers.purposes.join(' · '))}<br>Version ${state.brain.version} · reviewed ${esc(state.brain.reviewedAt.slice(0,10))}`:'Complete the interview and review the answers with your client before activating.'}</p></div><div class="panel" style="padding:22px"><h2>What your answers change</h2><p class="subtitle">Opportunity ranking uses financing purpose, property type, province and amount range. Optional city preferences add ranking context.</p><p class="subtitle">Mission Control shows matching opportunities, suggested qualification questions, preferred playbooks and your meeting target.</p><p class="subtitle">Strengths, lender access, exclusions and contact instructions appear as briefing context requiring human review. They are not automatic credit or eligibility decisions.</p></div><div class="notice">Interview answers are self-reported. Draft and active versions are separate. This prototype saves them in this browser only.</div></section></div>`}
function captureBrain(){if(brainStep===4)return;let form=$('#brainForm');if(!form)return;let data=new FormData(form),b=brainDraft();for(const [k,l,t] of brainSections[brainStep].fields)b[k]=t==='checks'?data.getAll(k):String(data.get(k)||'').trim()}
function brainJump(i){captureBrain();save();brainStep=i;render()}function brainMove(d){brainJump(brainStep+d)}function saveBrainDraft(){captureBrain();save();toast('Interview draft saved. Active dashboard is unchanged.')}
function brainReview(b){return `<div class="details">${[['Practice',b.name],['Interview participant',b.interviewee],['Ideal client',b.ideal],['Specialties',b.purposes.join(', ')],['Property / assets',b.properties.join(', ')],['Territory',b.regions.join(', ')+(b.cities?' · '+b.cities:'')],['Financing range',money(b.min)+' – '+money(b.max)],['Appointment goal',b.goal+' held qualified / month; '+b.capacity+' new calls / week']].map(([k,v])=>`<div><small>${k}</small>${esc(v||'Not answered')}</div>`).join('')}</div>${[['Positioning',b.positioning],['Strengths',b.strength],['Support gaps',b.gap],['Lender access · self-reported',b.lenders],['Relevant experience',b.experience],['Qualification requirements',b.qualification],['Exclusions · manual review',b.exclusions],['Contact instructions · manual review',b.restrictions],['Preferred GTM plays',b.channels.join(', ')],['Call offer',b.offer]].map(([k,v])=>`<div class="wirebox"><b>${k}</b><p style="white-space:pre-wrap">${esc(v||'Not answered')}</p></div>`).join('')}<label class="task"><input id="brainReviewed" type="checkbox"><span>I reviewed these answers with the client and am ready to use them for prioritization.</span></label>`}
function brainErrors(b){let e=[];if(!b.name||!b.interviewee||!b.ideal)e.push('Complete team name, interview participant and ideal client in step 1.');if(!b.purposes.length||!b.properties.length||!b.regions.length)e.push('Select financing specialties, property / asset types and provinces in step 2.');if(!b.min||!b.max||!Number.isFinite(Number(b.min))||!Number.isFinite(Number(b.max))||Number(b.min)<0||Number(b.max)<=0||Number(b.min)>Number(b.max))e.push('Set a valid financing range in step 2.');if(!b.strength||!b.gap||!b.qualification)e.push('Complete strengths, support gaps and qualification requirements in step 3.');if(!b.channels.length||!b.offer||!Number.isInteger(Number(b.goal))||Number(b.goal)<1||!Number.isInteger(Number(b.capacity))||Number(b.capacity)<1)e.push('Set appointment strategies, call offer, a positive whole-number goal and weekly capacity in step 4.');return e}
function activateBrain(){let b=brainDraft(),errors=brainErrors(b);if(!$('#brainReviewed')?.checked)errors.push('Confirm that you reviewed the interview with your client.');if(errors.length){$('#brainError').innerHTML=errors.map(esc).join('<br>');return}state.brain={answers:structuredClone(b),version:(state.brain?.version||0)+1,reviewedAt:new Date().toISOString(),provenance:'Client interview · self-reported'};Object.assign(state.profile,{name:b.name,territory:b.regions.join(', '),min:b.min,max:b.max,focus:b.purposes.join(', '),strength:b.strength,gap:b.gap});state.goal=Number(b.goal);state.tasks=[false,false,false];log('Activated Client Brain version '+state.brain.version);nav('overview');toast('Client Brain activated. Priorities, playbooks and meeting goal updated.')}
function opportunityPurpose(o){return o.purpose||({'Construction financing':'Construction / development','Development financing':'Construction / development','Acquisition & bridge':'Acquisition / bridge','Term refinance':'Commercial refinance','Commercial refinance':'Commercial refinance','Owner-occupied purchase':'Owner-occupied property'}[o.fit])||'Unknown'}
function matchBrain(o){if(!state.brain)return {eligible:true,score:o.score,reasons:['Complete Client Brain to calculate specialization fit.'],unknown:false};let b=state.brain.answers,p=opportunityPurpose(o),region=o.province||(seed.some(s=>s.id===o.id)?'BC':null),reasons=[],score=0,unknown=false,eligible=true;for(const [label,ok,points]of [['financing specialty',p==='Unknown'?null:b.purposes.includes(p),40],['property / asset type',o.type?b.properties.includes(o.type):null,25],['province',region?b.regions.includes(region):null,15],['amount range',Number.isFinite(o.amount)?o.amount>=Number(b.min)&&o.amount<=Number(b.max):null,20]]){if(ok===null){unknown=true;reasons.push('Missing '+label+' — review required')}else if(ok){score+=points;reasons.push('Matches '+label)}else{eligible=false;reasons.push('Outside selected '+label)}}let cities=b.cities.split(',').map(s=>s.trim().toLowerCase()).filter(Boolean);if(cities.length)reasons.push(cities.includes(o.city.toLowerCase())?'Preferred city':'Outside preferred cities · not excluded');return {eligible,score,reasons,unknown,cityBoost:cities.includes(o.city.toLowerCase())?1:0}}
function rankedOpps(onlyMatches=false){let a=state.opps.map(o=>({o,m:matchBrain(o)}));if(state.brain&&onlyMatches)a=a.filter(x=>x.m.eligible&&!x.m.unknown);return a.sort((a,b)=>Number(b.m.eligible&&!b.m.unknown)-Number(a.m.eligible&&!a.m.unknown)||b.m.score-a.m.score||(b.m.cityBoost||0)-(a.m.cityBoost||0)||a.o.id-b.o.id).map(x=>x.o)}
function recommendedPlays(){if(!state.brain)return [0,1];let b=state.brain.answers;return plays.map((p,i)=>({i,score:(b.channels.includes(p.name)?100:0)+((i===0&&b.purposes.includes('Construction / development')||i===1&&b.purposes.includes('Commercial refinance')||i===3&&b.purposes.includes('Owner-occupied property'))?20:0)})).sort((a,b)=>b.score-a.score).map(x=>x.i)}
function brainBanner(){if(!state.brain)return `<div class="prioritybanner"><span class="symbol">◇</span><span><b>Start with a client interview.</b><br>Tell Mission Control which financing requests you specialize in.</span><button class="primary" onclick="nav('brain')">Build Client Brain →</button></div>`;let b=state.brain.answers,count=rankedOpps(true).length;return `<div class="prioritybanner"><span class="symbol">◇</span><span><b>Personalized for ${esc(b.name)}</b><br>${esc(b.purposes.join(' · '))} · ${money(b.min)}–${money(b.max)} · ${esc(b.regions.join(', '))}<br>${count} matching sample opportunities · ${esc(b.offer)} · up to ${esc(b.capacity)} new calls/week</span><button class="textbutton" onclick="nav('brain')">Review Client Brain ↗</button></div>`}
function brainFocus(){let b=state.brain?.answers;if(!b)return [['Complete the client interview','Define specialties and qualification requirements.','Client Brain'],['Verify sponsor authority','Confirm who can discuss financing.','Research'],['Prepare the next discovery call','Review current debt and financing timing.','Meeting']];return rankedOpps(true).slice(0,3).map(o=>['Qualify '+o.name,b.qualification,'Research']).concat(rankedOpps(true).length?[]:[['Review financing coverage','No current sample opportunities match your specialization. Broaden research coverage or review the profile.','Research']])}
function brainDetail(o){let m=matchBrain(o);return `<h3>Client Brain matching</h3><p>${state.brain?'Rules-based specialization score: '+m.score+'/100 · '+(m.unknown?'Review missing fields':m.eligible?'Within selected mandate':'Outside selected mandate'):'Client Brain interview not activated.'}</p><ul>${m.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>${state.brain?`<p><b>Ask before accepting:</b> ${esc(state.brain.answers.qualification)}</p><p><b>Manual exclusions:</b> ${esc(state.brain.answers.exclusions||'None stated')}</p><p><b>Team support gaps:</b> ${esc(state.brain.answers.gap)}</p><p><b>Lender access · self-reported:</b> ${esc(state.brain.answers.lenders||'Not supplied')}</p>`:''}`}
function discoveryQuestions(o){const common=['Who is authorized to discuss this request, and when is financing required?','What financing is already in place, and what amount is being requested?'];const questions={
'Construction / development':['What approvals, budget, equity and construction schedule are documented?','Who is the builder, and what is the expected repayment or takeout plan?'],
'Acquisition / bridge':['What are the purchase price, closing date and available equity?','What event or permanent financing would repay the bridge?'],
'Commercial refinance':['What are the current balance, maturity and payout conditions?','What property income, occupancy and intended use of proceeds can be documented?'],
'Owner-occupied property':['How much of the property will the business occupy?','What purchase terms, equity and business financial records are available?'],
'Working capital':['What operating cash-flow need and use of funds are being addressed?','What revenue, existing debt and repayment sources can be documented?'],
'Equipment financing':['What equipment, vendor quotation and intended use are documented?','What deposit, equipment condition and repayment cash flow are available?'],
'Receivables / asset-based lending':['What eligible assets, receivables ageing and customer concentrations are documented?','What existing liens, reporting capability and facility requirements need review?'],
'Business acquisition':['What purchase structure, financial history and buyer equity are documented?','What due-diligence stage, closing conditions and repayment sources apply?']};return [...common,...(questions[opportunityPurpose(o)]||['Confirm the financing purpose before selecting specialty questions.'])]}
function exportBrain(){captureBrain();save();let b=state.brain?.answers;if(!b){toast('Activate the reviewed interview before exporting Client Brain.');return}let lines=['# client.brain.md','',`Version: ${state.brain.version}`,`Reviewed: ${state.brain.reviewedAt}`,'Source: Client interview; self-reported. No lending authority or commitment is established.',''];for(const s of brainSections)for(const[k,l]of s.fields)lines.push('## '+l,'',Array.isArray(b[k])?b[k].map(v=>'- '+v).join('\n'):String(b[k]??''),'');lines.push('## Matching rules','','40 points financing purpose; 25 property/asset type; 15 province; 20 amount range. All four must match and be known to appear in the personalized shortlist. City is a tie-break preference. Exclusions, lender access and contact instructions require human review.');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/markdown'}));a.download='client.brain.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

page=location.hash.slice(1)||'overview';render();
